-- PULIH abt-murtad-8529-30okt: 8529 dikembalikan persis (hanya bila isinya persis hasil paket).
START TRANSACTION;
UPDATE abt_variabel SET sql_query = REPLACE(CONVERT( USING latin1), 'aps_badilag.', CONCAT(DATABASE(), '.'))
 WHERE no_var = 8529 AND MD5(REPLACE(sql_query, CONCAT(DATABASE(), '.'), 'aps_badilag.')) = '1fdfa80464db4e96ceb58b8c60b14542';
COMMIT;
